  background: #140c1c;
  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  font-size: 12px;
  font-synthesis: none;
}

* {
  box-sizing: border-box;
}

body {
  min-height: 100vh;
  margin: 0;
  padding: 12px;
  color: #deeed6;
  background: #140c1c;
  image-rendering: pixelated;
}

button,
input {
  font: inherit;
}

