  display: flex;
  gap: 4px;
  margin-bottom: 12px;
  border-bottom: 2px solid #8595a1;
}

.tab {
  padding: 7px 10px;
  color: #8595a1;
  background: #442434;
  border: 2px solid #8595a1;
  border-bottom: 0;
  cursor: pointer;
}

